<script setup>
import {computed,inject,ref} from 'vue'
import {api} from '../api.js'
import AssistModel from './AssistModel.vue'
const props=defineProps({runId:String,comparisonId:String,caseId:String,canSuggest:Boolean,runType:String,embedded:Boolean}),emit=defineEmits(['suggestion'])
const work=inject('workspace'),ai=inject('ai'),opened=ref(false)
const expanded=computed(()=>props.embedded||opened.value)
const identity=computed(()=>`${props.comparisonId||props.runId}:${props.caseId}`)
const draft=computed(()=>ai.analyses[identity.value]),sid=computed(()=>ai.modelSession||work.state.session?.provider_session_id)
const names={CHECK_LABELS:'检查资料与标签',TOP_K_CHANGE:'调整 Top K',QUERY_REWRITE_TOGGLE:'切换 Query Rewrite',RERANK_TOGGLE:'切换 Rerank',KNOWLEDGE_UPDATE:'补充知识',HUMAN_REVIEW:'人工复核',NEW_BASELINE:'建立新初测'}
async function generate(){await work.action('AI 解读真实轨迹',async()=>{const key=identity.value;const body={request_id:crypto.randomUUID(),provider_session_id:sid.value,case_id:props.caseId,...(props.comparisonId?{comparison_id:props.comparisonId}:{run_id:props.runId})};ai.analyses[key]=await api.post('/ai/trace',body,{context:props.comparisonId?'comparison':props.runType==='RETEST'?'retest_trace':props.runType==='BASELINE'?'baseline_trace':'unknown'})})}
</script>
<template><div class="trace-assistant"><button v-if="!embedded" v-track="{action:'trace.expand',placement:'TraceAssistant.control_01',context:comparisonId ? 'comparison' : runType === 'RETEST' ? 'retest_trace' : runType === 'BASELINE' ? 'baseline_trace' : 'unknown'}" class="secondary" :aria-expanded="expanded" @click="opened=!opened">{{expanded?'收起 AI 解读':'AI 解读这题'}}</button><div v-if="expanded" class="ai-draft"><h4>让 AI 分析可以尝试的改法</h4><AssistModel/><p class="muted">调用模型 1 次，结合本题记录生成优化建议。</p><button v-track="{action:'trace.analyze',placement:'TraceAssistant.control_02',core:true,reason:('precondition'),context:comparisonId ? 'comparison' : runType === 'RETEST' ? 'retest_trace' : runType === 'BASELINE' ? 'baseline_trace' : 'unknown'}" class="primary" :disabled="!sid || !!work.state.busy" @click="generate">{{draft?'重新解读（新增 1 次请求）':'开始解读真实轨迹'}}</button><div v-if="draft"><p class="note">已生成分析 · {{draft.provider_call_count}} 次模型调用</p><template v-for="(title,key) in {facts:'发生了什么',issues:'值得关注的问题',hypotheses:'待验证的原因'}" :key="key"><h4>{{title}}</h4><article v-for="(row,i) in draft.content[key]" :key="i"><p>{{row.claim}}</p><p v-if="row.how_to_verify" class="muted">验证：{{row.how_to_verify}}</p><details><summary v-track="{action:'trace.evidence',placement:'TraceAssistant.control_03',context:comparisonId ? 'comparison' : runType === 'RETEST' ? 'retest_trace' : runType === 'BASELINE' ? 'baseline_trace' : 'unknown'}">对应原始依据：{{row.evidence_keys.join('、')}}</summary><pre v-for="k in row.evidence_keys" :key="k">{{JSON.stringify(draft.sources[k],null,2)}}</pre></details></article></template><h4>下一步建议</h4><article v-for="(row,i) in draft.content.suggestions" :key="i" class="builder-card"><strong>{{names[row.change_type]}}</strong><p>{{row.reason}}</p><p>验证：{{row.verification}}</p><p class="muted">副作用：{{row.side_effects}}</p><details><summary v-track="{action:'trace.suggestion_evidence',placement:'TraceAssistant.control_04',context:comparisonId ? 'comparison' : runType === 'RETEST' ? 'retest_trace' : runType === 'BASELINE' ? 'baseline_trace' : 'unknown'}">查看建议依据</summary><pre v-for="k in row.evidence_keys" :key="k">{{JSON.stringify(draft.sources[k],null,2)}}</pre></details><button v-track="{action:'trace.adopt',placement:'TraceAssistant.control_05',context:comparisonId ? 'comparison' : runType === 'RETEST' ? 'retest_trace' : runType === 'BASELINE' ? 'baseline_trace' : 'unknown'}" v-if="canSuggest" class="secondary" :disabled="!!work.state.busy" @click="emit('suggestion',{...row,case_id:caseId,run_id:runId,draft_id:draft.draft_id})">采用这条建议，填写优化方案 →</button></article><h4>结论边界</h4><p v-for="(text,i) in draft.content.limitations" :key="i">{{text}}</p><p class="muted">分析是建议；不会改写分数、人工复核或已保存的实验。</p></div></div></div></template>
